-- Helpers (pure functions, used by both client and server)
---------------------------------------------------------------------------------------------------

---@return string  e.g. 'wiwang_03_12' (floor 3, room 12)
function Rooms.RoomId(floor, number)
    return ('wiwang_%02d_%02d'):format(floor, number)
end

---@return number|nil floor, number|nil number
function Rooms.Parse(roomId)
    local f, n = tostring(roomId):match('^wiwang_(%d+)_(%d+)$')
    return tonumber(f), tonumber(n)
end

---@return string  e.g. 'Room 312'
function Rooms.Label(floor, number)
    return ('Room %d'):format(floor * 100 + number)
end

--- MLO origin height of a floor
function Rooms.FloorZ(floor)
    return Rooms.Base.z + (floor - 1) * Rooms.FloorHeight
end

--- rotate a 2D vector counter-clockwise by `deg` degrees
function Rooms.Rotate(x, y, deg)
    local r = math.rad(deg)
    local c, s = math.cos(r), math.sin(r)
    return x * c - y * s, x * s + y * c
end

--- World data for one room. Returns nil for an invalid floor / number.
---@return table|nil room { id, floor, number, label, rotation, bbMin, bbMax, centre, door, spawn(vec4), detail }
function Rooms.Get(floor, number)
    local t = Rooms.Template[number]
    if not t or floor < 1 or floor > Rooms.Floors then return nil end
    local base = vec3(Rooms.Base.x, Rooms.Base.y, Rooms.FloorZ(floor))
    local door = base + t.door
    local ix, iy = Rooms.Rotate(1.1, 0.0, t.rotation) -- 1.1 m inside the door
    return {
        id = Rooms.RoomId(floor, number),
        floor = floor,
        number = number,
        label = Rooms.Label(floor, number),
        rotation = t.rotation,
        bbMin = base + t.bbMin,
        bbMax = base + t.bbMax,
        centre = base + t.centre,                  -- z = floor level
        door = door,                               -- door entity origin (for AddDoorToSystem / interaction point)
        spawn = vec4(door.x + ix, door.y + iy, base.z + t.bbMin.z, (270.0 + t.rotation) % 360.0),
        detail = base + t.detail,
    }
end

--- axis-aligned test (the MLO is not rotated, so room boxes are world-axis-aligned)
function Rooms.IsInside(room, coords)
    return coords.x >= room.bbMin.x and coords.x <= room.bbMax.x
        and coords.y >= room.bbMin.y and coords.y <= room.bbMax.y
        and coords.z >= room.bbMin.z - 0.5 and coords.z <= room.bbMax.z + 0.5
end

--- room-local furniture coords -> world position + heading
function Rooms.ToWorld(room, lx, ly, lz, lh)
    local x, y = Rooms.Rotate(lx, ly, room.rotation)
    return vec3(room.centre.x + x, room.centre.y + y, room.centre.z + lz), ((lh or 0.0) + room.rotation) % 360.0
end

--- world position + heading -> room-local x, y, z, h
function Rooms.ToLocal(room, coords, heading)
    local x, y = Rooms.Rotate(coords.x - room.centre.x, coords.y - room.centre.y, -room.rotation)
    return x, y, coords.z - room.centre.z, ((heading or 0.0) - room.rotation) % 360.0
end

--- Which hotel floor are these coords on? nil when not inside the hotel tower.
function Rooms.FloorAt(coords)
    local b = Rooms.FloorBounds
    local lx, ly = coords.x - Rooms.Base.x, coords.y - Rooms.Base.y
    if lx < b.min.x or lx > b.max.x or ly < b.min.y or ly > b.max.y then return nil end
    local rel = coords.z - (Rooms.Base.z + b.min.z) -- height above the floor level of floor 1
    if rel < -0.5 then return nil end
    local floor = math.floor(rel / Rooms.FloorHeight) + 1
    if floor > Rooms.Floors then return nil end
    return floor
end
